package com.dating.backend.matching;
import com.dating.backend.entity.*;import jakarta.persistence.EntityManager;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class ProfileRewardsTest {
 @Autowired ProfileRewards rewards;@Autowired EntityManager em;User user;UserProfile profile;
 @BeforeEach void setup(){user=User.builder().email("completion@test.invalid").nickname("테스트").provider("LOCAL").status("ACTIVE").build();em.persist(user);profile=UserProfile.builder().userId(user.getId()).region("서울").job("개발자").mbti("ENFP").introduction("주말에는 산책과 독서를 즐기며 새로운 사람과 대화하는 것을 좋아합니다.").traitsJson("{\"answers\":{\"personality\":[\"차분한\"],\"hobbies\":[\"독서\"],\"talk_role\":[\"이야기하는 편\"]}}").build();em.persist(profile);for(int i=0;i<2;i++)em.persist(UserProfileImage.builder().userId(user.getId()).imageUrl("/uploads/profile/test"+i+".jpg").imageOrder(i).isMain(i==0).build());}
 @Test void allMilestonesAwardOnlyOnce(){assertEquals(100,rewards.get(user.getEmail()).percent());for(int n:new int[]{25,50,75,100}){rewards.claim(user.getEmail(),n);rewards.claim(user.getEmail(),n);}assertEquals(8,em.find(CreditWallet.class,user.getId()).getBalance());assertEquals(4L,em.createQuery("select count(e) from CreditEntry e where e.userId=:u",Long.class).setParameter("u",user.getId()).getSingleResult());assertTrue(rewards.get(user.getEmail()).steps().stream().allMatch(ProfileRewards.Step::claimed));}
 @Test void profileChangesDoNotResetClaim(){rewards.claim(user.getEmail(),25);profile.setTraitsJson(null);profile.setIntroduction("");profile.setJob("");rewards.claim(user.getEmail(),25);assertEquals(2,em.find(CreditWallet.class,user.getId()).getBalance());}
 @Test void unmetInvalidAndSuspendedClaimsDenied(){profile.setTraitsJson(null);profile.setIntroduction("");assertEquals(60,rewards.get(user.getEmail()).percent());assertThrows(ResponseStatusException.class,()->rewards.claim(user.getEmail(),75));assertThrows(ResponseStatusException.class,()->rewards.claim(user.getEmail(),30));user.setStatus("SUSPENDED");assertThrows(ResponseStatusException.class,()->rewards.claim(user.getEmail(),25));assertNull(em.find(CreditWallet.class,user.getId()));}
 @Test void anotherMemberCannotClaimUsingSomeoneElsesProfile(){var other=User.builder().email("empty@test.invalid").nickname("빈프로필").provider("LOCAL").status("ACTIVE").build();em.persist(other);assertEquals(0,rewards.get(other.getEmail()).percent());assertThrows(ResponseStatusException.class,()->rewards.claim(other.getEmail(),25));assertEquals(100,rewards.get(user.getEmail()).percent());}
}
